function getWordsForGrade(gradeId) {
  const info = (typeof getGradeInfo === 'function') ? getGradeInfo(gradeId)
             : (window.getGradeInfo ? window.getGradeInfo(gradeId) : null);
  if (!info) return HANJA_WORDS.slice();
  return HANJA_WORDS.filter(function (w) { return w.minOrder <= info.order; });
}

function getRadical(char) {
  const r = CHAR_RADICAL[char];
  if (!r) return null;
  return { radical: r, name: RADICAL_NAMES[r] || r, extra: CHAR_RADICAL_EXTRA[char] };
}

if (typeof window !== 'undefined') {
  window.RADICAL_NAMES = RADICAL_NAMES;
  window.CHAR_RADICAL = CHAR_RADICAL;
  window.HANJA_WORDS = HANJA_WORDS;
  window.getWordsForGrade = getWordsForGrade;
  window.getRadical = getRadical;
}
if (typeof module !== 'undefined' && module.exports) {
  module.exports = { RADICAL_NAMES, CHAR_RADICAL, CHAR_RADICAL_EXTRA, HANJA_WORDS, getWordsForGrade, getRadical };
}
